package com.procurement.controller; import com.procurement.entity.*; import com.procurement.repository.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/notifications") public class NotificationController {private final UserRepository users;private final FarmerRepository farmers;private final NotificationRepository repo;public NotificationController(UserRepository users,FarmerRepository farmers,NotificationRepository repo){this.users=users;this.farmers=farmers;this.repo=repo;} @GetMapping public List<Notification> mine(Authentication a){User u=users.findByPhoneNumber(a.getName()).orElseThrow();Farmer f=farmers.findByUserId(u.getId()).orElseThrow();return repo.findByFarmerIdOrderByCreatedAtDesc(f.getId());}}
